	private static final class DemotableResource implements OptionalMaterialization.Demotable {
		private final LmdbQueryMemoryManager.Reservation memory;
		private final AtomicInteger closes;
		private boolean spilled;

		private DemotableResource(LmdbQueryMemoryManager.Reservation memory, AtomicInteger closes) {
			this.memory = memory;
			this.closes = closes;
		}

		@Override
		public boolean spilled() {
			return spilled;
		}

		@Override
		public boolean demote() {
			memory.close();
			spilled = true;
			return true;
		}

		@Override
		public void close() {
			memory.close();
			closes.incrementAndGet();
		}
	}
